    # Mark only where each update starts and stops; one running sum rebuilds the counters.
    return [0] * n

solution:
def apply_updates(n: int, updates: list[list[int]]) -> list[int]:
    diff = [0] * (n + 1)                 # diff[i] = counter i minus counter i - 1
    for start, end, delta in updates:
        diff[start] += delta
        diff[end + 1] -= delta           # the spare slot absorbs end == n - 1
    counters, level = [], 0
    for i in range(n):
        level += diff[i]
        counters.append(level)
    return counters

perf.naive:
def apply_updates(n: int, updates: list[list[int]]) -> list[int]:
    counters = [0] * n
    for start, end, delta in updates:
        for i in range(start, end + 1):
            counters[i] += delta
    return counters
